from collections import defaultdict

def count_words(text):
    counts = defaultdict(int)
    for word in text.split():
        counts[word] += 1
    return dict(counts)

result = count_words("apple banana apple cherry banana apple")
print(result["apple"], result["banana"], result.get("grape", 0))

def decorator_a(func):
    print("A applied")
    def wrapper(*args, **kwargs):
        print("A before")
        result = func(*args, **kwargs)
        print("A after")
        return result
    return wrapper

def decorator_b(func):
    print("B applied")
    def wrapper(*args, **kwargs):
        print("B before")
        result = func(*args, **kwargs)
        print("B after")
        return result
    return wrapper

@decorator_a
@decorator_b
def greet():
    print("Hello")

greet()

def make_multipliers():
    multipliers = []
    for i in range(4):
        def multiplier(x):
            return x * i
        multipliers.append(multiplier)
    return multipliers

m = make_multipliers()
print(m[0](10), m[1](10), m[2](10), m[3](10))

class A:
